"use strict";
// Module code that builds a function from a string: a fence that fires when
// the module evaluates.
const probe = new Function("return 7")();
class Fenced {
  constructor(label) {
    this.label = label;
    this.count = 0;
    this.probe = probe;
  }
  bump() {
    return ++this.count;
  }
}
exports.Fenced = Fenced;
